Here's a simple example using SDL library:

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL.h>
#include <SDL_image.h>
#include <time.h>

#define WIDTH 640
#define HEIGHT 480
#define SNAKE_SPEED 10
#define FPS 10

typedef struct {
    SDL_Rect pos;
    int length;
    int direction;
} snake_t;

typedef struct {
    SDL_Rect pos;
} food_t;

typedef struct {
    SDL_Window *window;
    SDL_Renderer *renderer;
    snake_t snake;
    food_t food;
} game_t;

void init_game(game_t *game) {
    // Initialize SDL, create window, and set up renderer
    // ...

    // Initialize snake and food
    game->snake.length = 3;
    game->snake.direction = 1;
    game->snake.pos.x = WIDTH / 2;
    game->snake.pos.y = HEIGHT / 2;

    game->food.pos.x = rand() % (WIDTH / 10) * 10;
    game->food.pos.y = rand() % (HEIGHT / 10) * 10;
}

void handle_input(game_t *game) {
    SDL_Event event;

    while (SDL_PollEvent(&event) != 0) {
        if (event.type == SDL_QUIT) {
            SDL_Quit();
            exit(0);
        }

        if (event.type == SDL_KEYDOWN) {
            switch (event.key.keysym.sym) {
                case SDLK_UP:
                    game->snake.direction = -1;
                    break;
                case SDLK_DOWN:
                    game->snake.direction = 1;
                    break;
                case SDLK_LEFT:
                    game->snake.direction = -game->snake.length;
                    break;
                case SDLK_RIGHT:
                    game->snake.direction = game->snake.length;
                    break;
            }
        }
    }
}

void move_snake(game_t *game) {
    SDL_Rect old_pos = game->snake.pos;

    game->snake.pos.x += game->snake.direction * SNAKE_SPEED;
    game->snake.pos.x = (game->snake.pos.x + WIDTH) % WIDTH;
    game->snake.pos.y += game->snake.direction / game->snake.length * SNAKE_SPEED;
    game->snake.pos.y = (game->snake.pos.y + HEIGHT) % HEIGHT;

    if (game->snake.length > 1 && SDL_HasCollidedRect(&old_pos, &game->snake.pos)) {
        printf("Game Over!\n");
        SDL_Quit();
        exit(0);
    }
}

void check_collision(game_t *game) {
    if (game->snake.pos.x == game->food.pos.x && game->snake.pos.y == game->food.pos.y) {
        game->snake.length++;
        game->food.pos.x = rand() % (WIDTH / 10) * 10;
        game->food.pos.y = rand() % (HEIGHT / 10) * 10;
    }
}

void render(game_t *game) {
    SDL_Surface *snake_surface, *food_surface;
    SDL_Texture *snake_texture, *food_texture;

    snake_surface = IMG_Load("snake.bmp");
    food_surface = IMG_Load("food.bmp");

    if (!snake_surface || !food_surface) {
        printf("Error loading images: %s\n", IMG_GetError());
        SDL_Quit();
        exit(1);
    }

    snake_texture = SDL_CreateTextureFromSurface(game->renderer, snake_surface);
    food_texture = SDL_CreateTextureFromSurface(game->renderer, food_surface);

    SDL_RenderClear(game->renderer);

    for (int i = 0; i < game->snake.length; i++) {
        SDL_Rect snake_rect = game->snake.pos;
        snake_rect.x -= i * SNAKE_SPEED;

        SDL_RenderCopy(game->renderer, snake_texture, NULL, &snake_rect);
    }

    SDL_RenderCopy(game->renderer, food_texture, NULL, &game->food.pos);

    SDL_RenderPresent(game->renderer);

    SDL_FreeSurface(snake_surface);
    SDL_FreeSurface(food_surface);
    SDL_DestroyTexture(snake_texture);
    SDL_DestroyTexture(food_texture);
}

int main(int argc, char *argv[]) {
    game_t game;
    Uint32 start_time, current_time, elapsed_time;

    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Error initializing SDL: %s\n", SDL_GetError());
        return 1;
    }

    TTF_Init();

    SDL_SetHint(SDL_HINT_RENDER_SCALE_QUALITY, "linear");

    init_window(&game.window, "Snake Game", WIDTH, HEIGHT, SDL_WINDOW_SHOWN);
    init_renderer(&game.renderer, game.window);

    init_game(&game);

    while (1) {
        start_time = SDL_GetTicks();

        handle_input(&game);
        move_snake(&game);
        check_collision(&game);
        render(&game);

        current_time = SDL_GetTicks();
        elapsed_time = current_time - start_time;

        if (elapsed_time < 1000 / FPS) {
            SDL_Delay(1000 / FPS - elapsed_time);
        }
    }

    SDL_Quit();
    TTF_Quit();

    return 0;
}
```

This example uses BMP images for the snake and food. Replace "snake.bmp" and "food.bmp" with the actual image files.

